"""Native-shaped disk trials; no calls, answers or scores are generated by a model."""
import json
import tarfile
import unittest

import acceptance
import injection
import protocol
import test_injection


class NativeRecordTests(unittest.TestCase):
    def setUp(self):
        self.f = test_injection.InjectionTests("test_each_prestart_retry_binds_new_job_and_matching_archive")
        self.f.setUp()
        self.addCleanup(self.f.doCleanups)
        f = self.f
        f.config["versions"]["skill"] = "2026.10.22.12"
        f.config.update(context_transport="agents-md-v1", receipt_policy="native-trial-v1", reflection_evidence="observed-v1")
        f.evo.install_context({"state": str(f.state)})
        with tarfile.open(f.snapshot, "w:gz") as handle:
            handle.add(f.state, arcname="agent_state")
        f.frozen = acceptance.snapshot(f.snapshot)["files"]
        for cell, (trial, trace) in zip(f.cells, f.trials):
            for point in ("before", "ready", "after"):
                record = protocol.read(trial / f"agent/penguin-agent-state-{point}.json")
                record["files"] = {k: injection.digest(raw) for k, raw in f.frozen.items()}
                test_injection.save(trial / f"agent/penguin-agent-state-{point}.json", record)
            rows = [json.loads(line) for line in trace.read_text().splitlines()]
            rows[0]["payload"]["system_prompt"] = "Native default prompt\n" + (f.state / "AGENTS.md").read_text()
            # No read-file Skill choreography; initial context already has all methods.
            rows = [r for r in rows if r.get("payload", {}).get("tool_call_id", "").startswith("answer")
                    or r.get("type") != "model_msg"]
            trace.write_text("".join(json.dumps(row) + "\n" for row in rows))
        cell = f.cells[0]
        self.identity = {k: cell[k] for k in ("agent_id", "expected_version", "provider", "model_id", "thinking_level", "case_id", "run")}
        self.req = {"identity": self.identity, "session_id": cell["session_id"], "benchmark": str(f.benchmark),
                    "snapshot": str(f.snapshot), "runtime": f.runtime, "config_value": f.config,
                    "launch": protocol.read(f.benchmark / cell["case_id"] / "statement/harbor-launch.json")}

    def run_record(self):
        return injection.canonical_worker_cell(self.req, self.f.evo, acceptance)

    def test_all_five_contexts_identical_and_canonical_parameters_not_worker_guesses(self):
        f = self.f
        hashes = []
        for cell in f.cells:
            self.req["session_id"] = cell["session_id"]
            self.req["identity"] = {k: cell[k] for k in self.identity}
            self.req["launch"] = protocol.read(f.benchmark / cell["case_id"] / "statement/harbor-launch.json")
            record = self.run_record()
            self.assertFalse(record["pending"])
            self.assertEqual(record["cell"]["thinking_level"], "xhigh")
            self.assertEqual(record["cell"]["score"], 50)
            self.assertTrue(record["audit"]["audit_passed"])
            hashes.append(record["audit"]["model_context"]["sha256"])
        self.assertEqual(len(set(hashes)), 1)

    def test_real_014_005_receipt_mismatch_uses_actual_runtime(self):
        from pathlib import Path
        fixture = protocol.read(Path(__file__).with_name("fixtures") / "native-worker-mismatch.json")
        path = self.f.trials[0][0] / "result.json"
        original = protocol.read(path)
        for observed in fixture["sources"]:
            actual = json.loads(json.dumps(original))
            self.assertEqual(observed["reported_thinking"], "medium")
            actual["config"]["agent"]["kwargs"]["thinking"] = observed["actual_cli_thinking"]
            actual["agent_result"]["metadata"]["thinking"] = observed["actual_metadata_thinking"]
            test_injection.save(path, actual)
            self.assertEqual(self.run_record()["cell"]["thinking_level"], "xhigh")
            self.assertNotEqual(self.run_record()["cell"]["thinking_level"], observed["reported_thinking"])

    def test_pending_cost_does_not_remove_score_or_become_zero(self):
        path = self.f.trials[0][0] / "result.json"
        value = protocol.read(path)
        value["agent_result"].pop("cost_usd")
        value["agent_result"]["metadata"]["cost_status"] = "pending"
        test_injection.save(path, value)
        record = self.run_record()
        self.assertEqual(record["cell"]["score"], 50)
        self.assertIsNone(record["cell"]["cost"])
        self.assertTrue(record["audit"]["audit_passed"])

    def test_worker_completion_is_not_harbor_completion(self):
        path = self.f.trials[0][0] / "result.json"
        value = protocol.read(path)
        value["finished_at"] = None
        test_injection.save(path, value)
        self.assertTrue(self.run_record()["pending"])
        self.assertNotIn("cell", self.run_record())

    def test_new_protocol_waits_for_original_job_not_only_terminal_trial(self):
        self.f.config["versions"]["skill"]="2026.10.23.1"
        trial=self.f.trials[0][0];job_result=trial.parent/"result.json"
        test_injection.save(job_result,{"finished_at":None,"stats":{"n_running_trials":1}})
        self.assertTrue(self.run_record()["pending"])
        test_injection.save(job_result,{"finished_at":"synthetic-end","stats":{"n_running_trials":0}})
        self.assertFalse(self.run_record()["pending"])

    def test_real_runtime_wrong_state_and_wrong_loaded_text_still_rejected(self):
        path = self.f.trials[0][0] / "result.json"
        original = protocol.read(path)
        bad = json.loads(json.dumps(original))
        bad["agent_result"]["metadata"]["thinking"] = "medium"
        test_injection.save(path, bad)
        with self.assertRaisesRegex(ValueError, "runtime differs"):
            self.run_record()
        test_injection.save(path, original)
        rows = self.f.trace_rows()
        rows[0]["payload"]["system_prompt"] = "Native context WITHOUT the frozen Skill"
        self.f.save_rows(rows)
        with self.assertRaisesRegex(ValueError, "absent or duplicated"):
            self.run_record()

    def test_missing_prompt_receipt_keeps_diagnostic_measurement(self):
        rows = self.f.trace_rows()
        rows[0]["payload"].pop("system_prompt")
        self.f.save_rows(rows)
        record = self.run_record()
        self.assertEqual(record["cell"]["score"], 50)
        self.assertFalse(record["audit"]["audit_passed"])
        self.assertTrue(record["audit"]["diagnostic_only"])
        self.assertEqual(record["audit"]["audit_status"], "pending")


if __name__ == "__main__":
    unittest.main()
